image_url.description:
A direct link to an online image or a Base64-encoded local image that will serve as the first frame for the video.
Image specifications: 
- format must be JPG, JPEG, or PNG; 
- aspect ratio should be greater than 2:5 and less than 5:2; 
- the shorter side must exceed 300 pixels; 
- file size must not exceed 20MB.

x-codeSamples.source:
const response = await fetch('https://api.aimlapi.com/v2/video/generations', {
  method: 'POST',
  headers: {
    'Authorization': 'Bearer <YOUR_AIMLAPI_KEY>',
    'Content-Type': 'application/json',
  },
  body: JSON.stringify({
  "model": "minimax/h3-max",
  "prompt": "Describe what you want the model to generate.",
  "image_url": "https://example.com/input.jpg",
  "duration": 5
}),
});

console.log(await response.json());

import requests

response = requests.post(
    "https://api.aimlapi.com/v2/video/generations",
    headers={
        "Authorization": "Bearer <YOUR_AIMLAPI_KEY>",
        "Content-Type": "application/json",
    },
    json={'model': 'minimax/h3-max', 'prompt': 'Describe what you want the model to generate.', 'image_url': 'https://example.com/input.jpg', 'duration': 5},
)

print(response.json())
